import os,json,subprocess
from pathlib import Path
src=Path("/etc/lowcost-europa")
root=Path("/srv/projects/lowcost-europa")
priv=root/"private";dst=priv/"systemd-env"
out={"project":"lowcost-europa","status":"BLOCKED","changed":False}
def states():
 return {n:subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip() for n in ("ssh","nginx","lowcost-europa","fadego-staging","pink-iptv-backend","pm2-root")}
moved=False
try:
 if not src.is_dir() or src.is_symlink() or not priv.is_dir() or priv.is_symlink() or dst.exists() or dst.is_symlink():raise RuntimeError("source_or_destination_collision")
 old=src.stat()
 if old.st_dev!=priv.stat().st_dev or old.st_uid!=0:raise RuntimeError("origin_mismatch")
 baseline=states()
 os.rename(src,dst);moved=True
 os.symlink(str(dst),src)
 a=dst.stat()
 if not src.is_symlink() or src.resolve(strict=True)!=dst or (a.st_ino,a.st_dev,a.st_uid,a.st_gid,a.st_mode&0o777)!=(old.st_ino,old.st_dev,old.st_uid,old.st_gid,old.st_mode&0o777):raise RuntimeError("source_identity_changed")
 if not (dst/"lowcost-europa.env").is_file() or not (src/"lowcost-europa.env").is_file():raise RuntimeError("environment_file_missing")
 if states()!=baseline:raise RuntimeError("service_state_changed")
 out.update(status="MOVED_VERIFIED",changed=True,canonical="private/systemd-env",alias="/etc/lowcost-europa",owner_and_inode_preserved=True,service_states_unchanged=True)
except Exception as e:
 out["reason"]=str(e)[:140]
 try:
  if src.is_symlink() and src.resolve(strict=False)==dst:src.unlink()
  if moved and dst.is_dir() and not src.exists():os.rename(dst,src)
 except Exception:out["rollback"]="INCOMPLETE"
print(json.dumps(out,sort_keys=True))
if out["status"]!="MOVED_VERIFIED":raise SystemExit(3)
